			/*
			 * 사용자 정의 컨트롤에서 insert 이벤트 발생 시 호출.
			 * 신규 클릭 이벤트
			 */
			function onComBtnGridInsert(e){
			    var comBtnGrid = e.control;
			    
			    /* 2022-12-19 1. 각 단위업무별로 마감기준값의 기본 세팅
			    ==> 월마감 추가 클릭하거나 일괄마감일 생성으로 기관정보를 가져올시 마감적용기준의 기본값을 세팅해주세요
			    ==> DDLN_APLCN_CRTR_SE_CD의 추가값에 기본세팅해야 하는 단위업무구분코드를 등록해놨습니다.*/
			    var ddlnCd = "";    
			    var voDdlnCode = app.lookup("dsDDLN_APLCN_CRTR_SE_CD");
			    for(var idx = 0; idx < voDdlnCode.getRowCount(); idx++){
			        var rowData = voDdlnCode.getRowData(idx);
			        
			        var addVal = rowData.ADDTNG_MNG_VALUE1;
			           if (addVal != "" && addVal != null){
			//               console.log(addVal);
			               if(addVal.indexOf(untTaskwk) > -1){
			                   ddlnCd = rowData.CMMNS_CD_VALUE;
			                   break;
			               }
			           } 
			    }
			    
			    var voDataSet  = app.lookup("dsSEC330");
			    var rowIndex = voDataSet.getRowStatedIndices(cpr.data.tabledata.RowState.INSERTED);
			    
			    for(var idx = 0; idx < rowIndex.length; idx++){
			        
			//        console.log(moment().month(11).format("YYYYMMDD"));
			        var beforeMonth = moment().subtract("1", "month").format("YYYYMM");
			        
			                                                        /* @TODO 전월로 셋팅해야함 당월 아님*/
			        voDataSet.setValue(rowIndex[idx], "DDLN_YM"             , beforeMonth);           /* 당월*/
			        voDataSet.setValue(rowIndex[idx], "DDLN_APLCN_CRTR_SE_CD" , ddlnCd);           /* 해당단위마감월일*/
			        voDataSet.setValue(rowIndex[idx], "REG_INST_NO"         , instNo);            /* 등록기관번호*/
			        voDataSet.setValue(rowIndex[idx], "REG_INST_NM"         , instNm);            /* 등록기관명*/
			//        voDataSet.setValue(rowIndex[idx], "RGTR_NO"             , enfsnNo);           /* 등록자번호(종사자번호)*/
			        voDataSet.setValue(rowIndex[idx], "RGTR_NM"             , userNm);             /* 등록자명(종사자명)*/
			        voDataSet.setValue(rowIndex[idx], "REG_YMD"             , vsToday);           /* 등록일자(이번달)*/
			        voDataSet.setValue(rowIndex[idx], "DDLN_YN"             , "Y");               /* 마감여부*/  
			        voDataSet.setValue(rowIndex[idx], "UNT_TASKWK_SE_CD"    , untTaskwk);         /* 단위업무구분코드*/              
			    }
			    
			    fn_setDtlCrud("UPDATE");
			    
			    app.lookup("grdMonthDdlnList").redraw();
			}

