			/**
			 *  동일 마감연월 기관 체크
			 */
			function monthDdlnRowChk(){
			    
			    var voDataSet       = app.lookup("dsSEC330");
			    var voDataSetRowCnt = app.lookup("dsSEC330").getRowCount();
			    var grdListCnt      = app.lookup("grdMonthDdlnList").getRowCount();
			    
			    if (grdListCnt <= 0) return false;

			    var sDdlnYm     = "";
			    var sDdlnYmTemp = "";
			    var sInstNo     = "";
			    var sInstNotemp = "";
			    var boInst      = true;    
			    for (var idx = 0; idx < grdListCnt; idx++){
			        
			        var rowData = voDataSet.getRowData(idx);
			        
			            /* 첫번째 로우 담기*/
			            sDdlnYm = rowData["DDLN_YM"]; 
			            sInstNo = rowData["INST_NO"]; 
			            
			            if (idx > 0 && (sDdlnYmTemp == sDdlnYm) && (sInstNotemp == sInstNo)){
			                
			                util.Msg.alert(app, "동일년월/동일기관이 이미 입력되어있습니다.\n확인 후 저장바랍니다.", null, function(){
			                    
			                }, "월마감관리");
			                boInst = false;
			                break;
			            }
			            sDdlnYmTemp = rowData["DDLN_YM"];
			            sInstNotemp = rowData["INST_NO"];            
			    }
			    console.log(boInst);
			    return boInst;
			}

			/**
			 *  마감월 여부 체크
			 */
			function monthDdlnDateChk(){

			    var voDataSet       = app.lookup("dsSEC330");
			    var voDataSetRowCnt = app.lookup("dsSEC330").getRowCount();
			    var grdListCnt      = app.lookup("grdMonthDdlnList").getRowCount();
			    var boYearDd        = true;
			    
			    // 마감연월 (당일기준 전전월은 수정불가)
			    if (grdListCnt <= 0){
			        var psTitle = "센터별마감목록 저장";
			        var psMsgId = "저장할 목록이 없습니다.\n확인 후 다시 저장하시기 바랍니다.";
			        
			        util.Msg.alert(app, psMsgId, null, function(){
			            util.Control.setFocus(app, "dti_DDLN_YEAR");
			        }, psTitle);
			        
			    }else if (grdListCnt >= 1){
			        for (var idx = 0; idx < grdListCnt; idx++){
			            
			            var sDdlnYm = voDataSet.getRowData(idx).DDLN_YM;  /* 마감년월*/
			            var sYear   = sDdlnYm.substring(0, 4);            /* 마감년도*/      
			            var sMonth  = sDdlnYm.substring(4, 6);            /* 마감월*/
			            
			            var iYear         = ValueUtil.fixNumber(sYear);
			            var iCurrentYear  = ValueUtil.fixNumber(vsCurrentYear);
			            var ichkYear      = iCurrentYear - iYear;       /* 현재연도 - 입력연도*/
			            
			            var iMonth        = ValueUtil.fixNumber(sMonth);
			            var iCurrentMonth = ValueUtil.fixNumber(vsCurrentMonth);
			            var ichkMonth     = iCurrentMonth - iMonth;     /* 현재월 - 입력월*/            
			            
			            var psTitle = "마감년월";
			            var psMsgId = "두달 경과 마감월은 마감이 완료되어 수정 또는 저장이 불가합니다.\n마감년월을 확인바랍니다.";
			            
			            var psTitle1 = "마감년월";
			            var psMsgId1 = "당월이후 마감이 선택되었습니다.\n당월이후 마감은 해당월에 마감바랍니다.";            
			            
			            /* 올해이전연도 선택*/
			            if (ichkYear > 0){
			                util.Msg.alert(app, psMsgId, null, function(){
			                    util.Grid.selectRow(app, "grdMonthDdlnList", idx);  
			                }, psTitle);
			                boYearDd = false;
			                break;
			            /* 올해이후연도 선택*/
			            }else if(ichkYear < 0){
			                util.Msg.alert(app, psMsgId1, null, function(){
			                    util.Grid.selectRow(app, "grdMonthDdlnList", idx);
			                }, psTitle1);
			                boYearDd = false;                
			                break;
			            /* 올해 전전달 선택(마감종료)*/      
			            }else if(ichkYear == 0 && ichkMonth >= 2){
			                util.Msg.alert(app, psMsgId, null, function(){
			                    util.Grid.selectRow(app, "grdMonthDdlnList", idx);  
			                }, psTitle);
			                boYearDd = false;                
			                break;                
			            /* 올해 익월 선택(마감불가)*/
			            }else if(ichkYear == 0 && ichkMonth < 0){
			                util.Msg.alert(app, psMsgId1, null, function(){
			                    util.Grid.selectRow(app, "grdMonthDdlnList", idx);
			                }, psTitle1);
			                boYearDd = false;                
			                break;   
			            }        
			        }
			    }
			    return boYearDd;
			}

